package com.anssa8bu.ssafy.common.redis; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.assertj.core.api.Assertions.*; class RedisKeyGeneratorTest { @Test void createsNamespacedKeys(){var g=new RedisKeyGenerator("local","umi");UUID id=UUID.randomUUID();assertThat(g.trainingLease(id)).isEqualTo("local:umi:training-lease:"+id);assertThat(g.activeTrainingProfile()).isEqualTo("local:umi:training-profile:active");} @Test void rejectsUnsafeSegments(){assertThatThrownBy(()->new RedisKeyGenerator("../prod","umi")).isInstanceOf(IllegalArgumentException.class);} }
